import SidebarAlumno from "./SidebarAlumno";
import { useState } from "react";
import MisClases from "./alumno/MisClases";
import PanelControl from "./alumno/PanelControl";

function DashboardAlumno({ user, onLogout }) {
  const [seccion, setSeccion] = useState("clases");

  return (
    <div className="flex h-screen">
      <SidebarAlumno setSeccion={setSeccion} />
      <div className="flex-1 p-4 overflow-y-auto bg-gray-100">
        {seccion === "clases" && <MisClases user={user} />}
        {seccion === "panel_control" && (
          <PanelControl user={user} onLogout={onLogout} />
        )}
      </div>
    </div>
  );
}

export default DashboardAlumno;
